// Written by tools/bake.ts (npm run bake) — do not edit. Every scene, the changes of the digits it has a file for, how
// long each plays and its sounds. The file is src/animations/<id>.anim, one section a key: key m<d> = minute
// d -> d+1, t<t> = tens of minutes t9 -> (t+1)0, h<HH> = HH:59 -> next hour, h12a = 12:59 -> 01:00 (12-hour clock); the focus timer countdown in color (f = focus, b = break): fm<d> = d -> d-1, ft<t> = t0 -> (t-1)9, fh<h> = h:00 -> (h-1):59; bk<n> = the focus over, into an n-minute break; i = an idle (no digits in it), e = an event.
// Kept small on purpose: the app holds all of it in its 192 KiB heap (see tools/bake.ts).
export interface Baked {
  id: string;
  name: string;
  tier: "minute" | "ten" | "hour" | "idle" | "event" | "tap" | "night";
  rare?: boolean;
  variantOf?: string;
  /** Its changes: the list KEYS[k]. */
  k: number;
  /** How long each plays, in frames at 60 fps: 3 base-36 characters each, in the order of KEYS[k]. */
  f: string;
  /** Its sounds: 2 base-36 characters each (the index of the notes in CUES, "--" none), in the order of KEYS[k]. */
  c?: string;
}

