/** Where `key` is in the scene's list of changes; -1 when it has no file for it. */
function keyAt(s: Baked, key: string): number {
  const list = "," + KEYS[s.k] + ",";
  const p = list.indexOf("," + key + ",");
  if (p < 0) return -1;
  let n = 0;
  for (let i = 0; i < p; i++) if (list.charAt(i) === ",") n++;
  return n;
}

/** How long the scene's file for `key` plays, in ms; 0 when it has none. */
export function msOf(s: Baked, key: string): number {
  const i = keyAt(s, key);
  return i < 0 ? 0 : Math.round((parseInt(s.f.slice(i * 3, i * 3 + 3), 36) * 1000) / 60);
}

/** The sound notes of the scene's file for `key` (see CUES), or undefined when it has none. */
export function cueOf(s: Baked, key: string): string | undefined {
  const i = keyAt(s, key);
  if (i < 0 || !s.c) return undefined;
  const v = s.c.slice(i * 2, i * 2 + 2);
  if (v === "--") return undefined;
  let n = parseInt(v, 36), p = 0;
  while (n-- > 0) p = CUES.indexOf("|", p) + 1;
  const e = CUES.indexOf("|", p);
  return CUES.slice(p, e < 0 ? CUES.length : e);
}

